        return fields.iter().any(|field| types.contains_owned_bytes(&field.ty)).then(|| {
            error(program, "SPX-T268", format!(
                "owned-Bytes record `{}` must be monomorphic in this tranche", declaration.name,
            ), declaration.span)
        });
    }
