        ),
        NestedOwnedRecordAdmission::OutsideProfile => Some(error(
            program, "SPX-T268", format!(
                "owned-Bytes record `{}` must be a monomorphic acyclic record tree with only `Bytes` or direct Copy scalar leaves", declaration.name,
            ), declaration.span,
